// ***************
// Filename: blur_filter_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of blur_filter: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to blur_filter's logic on named ports, its
//   status comes back on input ports. Blurring filter: binomial (Gaussian)
//   reset kernel. The settings are copied at each frame start. Generated by
//   ip/scripts/regmap_gen.py from blur_filter_regs.json: edit the JSON and
//   regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "BLRF" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x14 FRAME_SIZE  RW   [15:0] width [31:16] height (>= (N+1)/2 each),
//                       reset {RESET_H, RESET_W}
//     0x18 SHIFT       RW   result right shift (normalisation), reset SHIFT
//     0x1C STATUS      RO   [15:0] frames filtered
//     0x20 INFO        RO   [3:0] N [11:8] COEF_W [23:16] C [31:24] CW
//     0x50 + 4 i K [N * N]   RW   signed coefficient i = r*N + c, reset
//                       KERNEL[i*32 +: 32]
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-11
module blur_filter_regs #(
  parameter int N = 5,  // kernel size: 3 or 5
  parameter int COEF_W = 12,  // coefficient width
  parameter logic [15:0] RESET_W = 16'd1920,  // FRAME_SIZE width at reset
  parameter logic [15:0] RESET_H = 16'd1080,  // FRAME_SIZE height at reset
  parameter logic [conv2d_pkg::KMAX*32-1:0] KERNEL = '0,  // kernel at reset
  parameter int SHIFT = 0  // SHIFT at reset
) (
  input  logic                        clk,             // clock
  input  logic                        rst_n,           // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]                  s_axil_awaddr,   // AXI4-Lite
  input  logic                        s_axil_awvalid,
  output logic                        s_axil_awready,
  input  logic [31:0]                 s_axil_wdata,
  input  logic [3:0]                  s_axil_wstrb,
  input  logic                        s_axil_wvalid,
  output logic                        s_axil_wready,
  output logic [1:0]                  s_axil_bresp,
  output logic                        s_axil_bvalid,
  input  logic                        s_axil_bready,
  input  logic [7:0]                  s_axil_araddr,
  input  logic                        s_axil_arvalid,
  output logic                        s_axil_arready,
  output logic [31:0]                 s_axil_rdata,
  output logic [1:0]                  s_axil_rresp,
  output logic                        s_axil_rvalid,
  input  logic                        s_axil_rready,
  output logic [32-1:0]               frame_size_o,    // FRAME_SIZE (RW): register value
  output logic                        frame_size_wr_o, // FRAME_SIZE: one-clock pulse at every software write
  output logic [5-1:0]                shift_o,         // SHIFT (RW): register value
  output logic                        shift_wr_o,      // SHIFT: one-clock pulse at every software write
  input  logic [32-1:0]               status_i,        // STATUS (RO): value read
  input  logic [32-1:0]               info_i,          // INFO (RO): value read
  output logic [(N * N)*(COEF_W)-1:0] k_o,             // K (RW): register value
  output logic [N * N-1:0]            k_wr_o           // K: one-clock pulse at every software write
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "BLRF";
  localparam logic [31:0] IP_VERSION = "1.00";
  localparam logic [31:0] IP_DATE    = 32'h10112026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_FRAME_SIZE = 8'h14;
  localparam logic [7:0] A_SHIFT = 8'h18;
  localparam logic [7:0] A_STATUS = 8'h1C;
  localparam logic [7:0] A_INFO = 8'h20;
  localparam logic [7:0] A_K = 8'h50;   // + 4 i, i < N * N
  localparam int MAP_WORDS = 45;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] frame_size_q;
  logic [31:0] shift_q;
  logic [31:0] k_q [N * N];
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      frame_size_q <= 32'({RESET_H, RESET_W});
      frame_size_wr_o <= 1'b0;
      shift_q <= 32'(SHIFT);
      shift_wr_o <= 1'b0;
      for (int i = 0; i < N * N; i++) k_q[i] <= 32'(KERNEL[i*32 +: 32]);
      k_wr_o <= '0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_STATUS || wa == A_INFO);   // writes to read-only words: SLVERR
      begin
        frame_size_wr_o <= wr_en && wa == A_FRAME_SIZE;
        if (wr_en && wa == A_FRAME_SIZE) frame_size_q <= (frame_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        shift_wr_o <= wr_en && wa == A_SHIFT;
        if (wr_en && wa == A_SHIFT) shift_q <= (shift_q & ~wmask) | (wr_data & wmask);
      end
      for (int i = 0; i < N * N; i++) begin
        k_wr_o[i] <= wr_en && wa == A_K + 8'(4 * i);
        if (wr_en && wa == A_K + 8'(4 * i)) k_q[i] <= (k_q[i] & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign frame_size_o = frame_size_q[32-1:0];
  assign shift_o = shift_q[5-1:0];
  always_comb for (int i = 0; i < N * N; i++) k_o[i*(COEF_W) +: COEF_W] = k_q[i][COEF_W-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_FRAME_SIZE: rd_data = frame_size_q;
      A_SHIFT: rd_data = shift_q;
      A_STATUS: rd_data = 32'(status_i);
      A_INFO: rd_data = 32'(info_i);
      default: begin
        for (int i = 0; i < N * N; i++)
          if (rd_addr_q == A_K + 8'(4 * i)) rd_data = k_q[i];
      end
    endcase
  end
endmodule
